<?php

namespace Tests\Feature\Filament\Admin\Resources;

use App\Constants\AuditRequestStatus;
use App\Filament\Admin\Resources\AuditRequests\Pages\EditAuditRequest;
use App\Filament\Admin\Resources\AuditRequests\Pages\ListAuditRequests;
use App\Jobs\GenerateAuditReport;
use App\Models\AuditRequest;
use Illuminate\Support\Facades\Queue;
use Livewire\Livewire;
use Spatie\Activitylog\Models\Activity;
use Tests\Feature\FeatureTest;

class AuditRequestChangeLogTest extends FeatureTest
{
    public function test_form_status_edit_logs_old_and_new_values_with_causer(): void
    {
        $admin = $this->createAdminUser();
        $audit = AuditRequest::factory()->create([
            'status' => AuditRequestStatus::NEEDS_FOLLOWUP->value,
        ]);

        Livewire::actingAs($admin)
            ->test(EditAuditRequest::class, ['record' => $audit->uuid])
            ->fillForm(['status' => AuditRequestStatus::HANDLED->value])
            ->call('save')
            ->assertHasNoFormErrors();

        $log = Activity::where('subject_type', AuditRequest::class)
            ->where('subject_id', $audit->id)
            ->where('event', 'updated')
            ->latest()
            ->first();

        $this->assertNotNull($log, 'Expected an activity log entry for the status change');
        $this->assertEquals($admin->id, $log->causer_id);
        $this->assertSame(AuditRequestStatus::NEEDS_FOLLOWUP->value, $log->properties['old']['status']);
        $this->assertSame(AuditRequestStatus::HANDLED->value, $log->properties['attributes']['status']);
    }

    public function test_retry_action_logs_status_change(): void
    {
        Queue::fake([GenerateAuditReport::class]);
        $admin = $this->createAdminUser();
        $audit = AuditRequest::factory()->create([
            'status' => AuditRequestStatus::FAILED->value,
            'failure_reason' => 'timeout',
        ]);

        Livewire::actingAs($admin)
            ->test(ListAuditRequests::class)
            ->callTableAction('retry', $audit);

        $log = Activity::where('subject_type', AuditRequest::class)
            ->where('subject_id', $audit->id)
            ->latest()
            ->first();

        $this->assertNotNull($log, 'Expected an activity log entry for the retry action');
        $this->assertEquals($admin->id, $log->causer_id);
        $this->assertSame(AuditRequestStatus::QUEUED->value, $log->properties['attributes']['status']);
    }

    public function test_mark_handled_action_logs_status_change(): void
    {
        $admin = $this->createAdminUser();
        $audit = AuditRequest::factory()->create([
            'status' => AuditRequestStatus::NEEDS_FOLLOWUP->value,
        ]);

        Livewire::actingAs($admin)
            ->test(ListAuditRequests::class)
            ->callTableAction('markHandled', $audit);

        $log = Activity::where('subject_type', AuditRequest::class)
            ->where('subject_id', $audit->id)
            ->latest()
            ->first();

        $this->assertNotNull($log, 'Expected an activity log entry for mark-handled');
        $this->assertEquals($admin->id, $log->causer_id);
        $this->assertSame(AuditRequestStatus::HANDLED->value, $log->properties['attributes']['status']);
    }

    public function test_non_status_changes_are_not_logged(): void
    {
        $admin = $this->createAdminUser();
        $audit = AuditRequest::factory()->create([
            'status' => AuditRequestStatus::NEW->value,
        ]);

        // Clear any creation log entries
        Activity::where('subject_type', AuditRequest::class)
            ->where('subject_id', $audit->id)
            ->delete();

        Livewire::actingAs($admin)
            ->test(EditAuditRequest::class, ['record' => $audit->uuid])
            ->fillForm(['admin_context' => 'Some new context without status change'])
            ->call('save')
            ->assertHasNoFormErrors();

        $log = Activity::where('subject_type', AuditRequest::class)
            ->where('subject_id', $audit->id)
            ->first();

        $this->assertNull($log, 'Non-status changes should not produce activity log entries');
    }
}
ENDOFFILE
